import { configureStore } from "@reduxjs/toolkit";
import usersReducer from "../Features/UserSlice";
import companyReducer from "../Features/CompanySlice"; // لو عندك هذا الملف

export const store = configureStore({
  reducer: {
    users: usersReducer,
    company: companyReducer, // تأكدي من الاسم بالضبط
  },
});
